import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import api from '../services/api';
import PageBanner from '../components/PageBanner';
import ProductCard from '../components/ProductCard';

const Category = () => {
  const { slug } = useParams();
  const [data, setData] = useState({ products: [], categories: [], totalPages: 1 });
  const [category, setCategory] = useState(null);

  useEffect(() => {
    api.get('/categories').then(res => {
      const cat = res.data.find(c => c.slug === slug);
      setCategory(cat);
      if (cat) {
        api.get('/products', { params: { category: cat.id, size: 12 } }).then(r => setData(r.data));
      }
    });
  }, [slug]);

  return (
    <>
      <PageBanner title={category?.name || 'Category'} items={[{ label: 'Home', to: '/' }, { label: 'Shop', to: '/shop' }, { label: category?.name || slug }]} />
      <section className="section">
        <div className="container">
          <div className="row">
            <div className="col-lg-3 col-md-4">
              <aside className="shop-sidebar">
                <div className="sidebar-widget">
                  <h5 className="widget-title">Categories</h5>
                  <ul className="category-list">
                    <li><Link to="/shop">All Products</Link></li>
                    {(data.categories || []).map(cat => (
                      <li key={cat.id}><Link to={`/category/${cat.slug}`} className={cat.slug === slug ? 'active' : ''}>{cat.name}</Link></li>
                    ))}
                  </ul>
                </div>
              </aside>
            </div>
            <div className="col-lg-9 col-md-8">
              {(data.products || []).length === 0 ? (
                <div className="empty-state">
                  <i className="bi bi-box-seam"></i>
                  <h4>No products found</h4>
                  <p className="text-muted">No products in this category yet.</p>
                  <Link to="/shop" className="btn-gold">Browse All Products</Link>
                </div>
              ) : (
                <div className="row">
                  {(data.products || []).map(p => <ProductCard key={p.id} product={p} />)}
                </div>
              )}
            </div>
          </div>
        </div>
      </section>
    </>
  );
};

export default Category;
